/// Toasts showing at once; older ones leave as new ones arrive.
pub const MAX_TOASTS: usize = 3;
const REMOTE_POLL_ACTIVE: Duration = Duration::from_secs(4);
const REMOTE_POLL_IDLE: Duration = Duration::from_secs(20);
/// The shortest regular gap between playback polls, which spend the Web API
/// quota.
const REMOTE_POLL_MIN: Duration = Duration::from_secs(15);
/// How long after a command to another device, or a switch to one, polls are
/// not held to `REMOTE_POLL_MIN`, so the result is confirmed before the
/// optimistic holds run out.
const REMOTE_COMMAND_WINDOW: Duration = Duration::from_secs(10);
/// With nobody able to see the window and nothing playing anywhere.
const REMOTE_POLL_UNSEEN: Duration = Duration::from_secs(30);
const REMOTE_FRESH: Duration = Duration::from_secs(60);
const SEARCH_DEBOUNCE: Duration = Duration::from_millis(150);
/// How old the saved resume point may grow while music plays.
const SESSION_REFRESH: Duration = Duration::from_secs(10);
/// Changed settings and session state are written this long after the
/// last write, so a run of changes is written once.
const SAVE_DELAY: Duration = Duration::from_secs(2);
/// Whether the playback engine can read this context again by itself.
fn context_rereadable(context: &str) -> bool {
    context == crate::tidal_engine::OFFLINE_CONTEXT
        || matches!(
            util::uri_kind(context),
            Some("album" | "playlist" | "mix" | "artist" | "toptracks" | "collection" | "station")
        )
}
/// How many previous songs the queue panel's History keeps.
pub const HISTORY_MAX: usize = 100;

/// How many upcoming shuffled songs the session keeps.
const SESSION_ORDER_LEN: usize = 100;
/// The longest the app sleeps in the tray with nothing due.
const HEADLESS_SLEEP: Duration = Duration::from_secs(2);
/// How long a playlist list TIDAL turned away waits before it is asked
/// for again.
const PLAYLISTS_RETRY: Duration = Duration::from_secs(60);
/// The quiet re-checks of a playlist write TIDAL has not confirmed yet start
/// this far apart and double up to the cap.
const SNAPSHOT_RECHECK_BASE: Duration = Duration::from_millis(500);
const SNAPSHOT_RECHECK_MAX: Duration = Duration::from_secs(15);
/// After this long the checks stop; the overlay stays until a read agrees.
const SNAPSHOT_RECHECK_GIVE_UP: Duration = Duration::from_secs(600);

/// A playlist's revision as milliseconds since the epoch. An edit answers with
/// a number, the playlist's own header with a date, so neither form can be
/// compared as text.
fn snapshot_millis(snapshot: &str) -> Option<i64> {
    let text = snapshot.trim();
    if let Ok(millis) = text.parse::<i64>() {
        return Some(millis);
    }
    // `+0000` becomes `+00:00`, the form the parser reads.
    let mut text = text.to_string();
    let bytes = text.as_bytes();
    if bytes.len() > 5
        && matches!(bytes[bytes.len() - 5], b'+' | b'-')
        && bytes[bytes.len() - 4..].iter().all(u8::is_ascii_digit)
    {
        text.insert(text.len() - 2, ':');
    }
    text.parse::<jiff::Timestamp>()
        .ok()
        .map(|time| time.as_millisecond())
}

/// Whether TIDAL's reported revision includes the write that returned
/// `expected`.
fn snapshot_confirms(reported: Option<&str>, expected: &str) -> bool {
    let Some(reported) = reported else {
        return false;
    };
    reported == expected
        || matches!(
            (snapshot_millis(reported), snapshot_millis(expected)),
            (Some(reported), Some(expected)) if reported >= expected
        )
}

/// Whether two revisions name the same moment, whatever their form.
fn same_snapshot(a: Option<&str>, b: Option<&str>) -> bool {
    match (a, b) {
        (None, None) => true,
        (Some(a), Some(b)) => {
            a == b
                || matches!(
                    (snapshot_millis(a), snapshot_millis(b)),
                    (Some(a), Some(b)) if a == b
                )
        }
        _ => false,
    }
}
/// How long background work goes on before the top bar's spinner shows it,
/// so fast answers never flash it.
const BACKGROUND_QUIET: Duration = Duration::from_secs(1);
/// How far into a song Previous restarts it rather than stepping back,
/// matching what the engine does during playback.
const RESTART_BEFORE_PREVIOUS: u32 = 3_000;

use crate::ui::toast_life;
const OPTIMISTIC_HOLD: Duration = Duration::from_millis(2500);

/// How long a newly started context remains visible while TIDAL catches up.
/// During local takeover, TIDAL may briefly alternate between old and new
/// context state.
const ASSUMED_CONTEXT_HOLD: Duration = Duration::from_secs(8);
/// How long the interface trusts its own play/pause over a polled state that
/// has not caught up yet. TIDAL can take a moment to report a command it
/// has already carried out.
/// How long after the last change a Luna plugin made to a playlist the app
/// reads it again (a duplicate scan changes it once per removed song).
const PLUGIN_PLAYLIST_QUIET: Duration = Duration::from_millis(1200);
const PLAYBACK_HOLD: Duration = Duration::from_secs(6);
/// Delay before checking playback again after a command.
const REMOTE_RECHECK: Duration = Duration::from_millis(1200);
/// Delay before checking the queue after a local change.
const QUEUE_RECHECK: Duration = Duration::from_millis(700);
/// Number of stale queue responses accepted before trusting TIDAL's state.
const QUEUE_STALE_RETRIES: u8 = 6;
/// How long a library write may go unanswered before a newer one for the
/// same song is sent anyway.
const SAVED_WRITE_PATIENCE: Duration = Duration::from_secs(30);
/// Duplicate queue requests within this window count as one click.
const QUEUE_ADD_DEBOUNCE: Duration = Duration::from_millis(1500);
/// How many played contexts the sidebar's Recently played order keeps.
const RECENT_CONTEXTS_KEPT: usize = 60;
/// Creator ids asked about in one request.
const USER_NAME_BATCH: usize = 24;
const CONTAINS_BATCH: usize = 40;

pub struct RemoteSnapshot {
    pub state: PlaybackState,
    pub received_at: Instant,
}

/// What a Play showed before it was answered, kept to put back if the engine
/// finds nothing to play: the bar must go on telling the true story.
struct PlayRollback {
    assumed: Option<AssumedContext>,
    shuffle_wanted: bool,
    shuffle_set_at: Option<Instant>,
    /// The Play itself turned Shuffle off (a page's Play does), so the
    /// engine's mode must be put back too.
    shuffle_turned_off: bool,
    at: Instant,
}

/// A context shown as playing before TIDAL confirms it.
#[derive(Clone)]
struct AssumedContext {
    uri: String,
    /// Shuffle state included in the play request, if any.
    shuffle: Option<bool>,
    at: Instant,
}

/// A track the interface shows before playback has reported its new state.
///
/// Local engine events are ordered, so its next track report settles the
/// intent. Remote playback is polled and may lag; one contradictory poll is
/// ignored and a second one settles on what TIDAL actually reports.
struct TrackIntent {
    uri: String,
    position_ms: u32,
    at: Instant,
    confirmation: TrackConfirmation,
}

/// What saving the edit dialog sends: only the details that changed.
struct PlaylistDetailChanges {
    name: Option<String>,
    description: Option<String>,
    public: Option<bool>,
    /// The description was cleared, which TIDAL doesn't allow.
    kept_description: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TrackConfirmation {
    Local,
    Remote { after_poll: u64, mismatches: u8 },
}

/// Upcoming context order before shuffle was toggled, used to detect lagging responses.
#[derive(Clone, Debug)]
struct QueueShufflePending {
    current_uri: Option<String>,
    context_uris: Vec<String>,
    at: Instant,
}

/// The playing item as the interface sees it, whichever device plays it.
#[derive(Clone, Debug, PartialEq)]
pub struct NowPlaying {
    pub local: bool,
    pub device_name: Option<String>,
    /// TIDAL's device type, such as "Smartphone", for the device's icon.
    pub device_kind: Option<String>,
    pub uri: String,
    pub id: Option<String>,
    pub title: String,
    pub artists: Vec<ArtistRef>,
    pub subtitle: String,
    pub album_name: String,
    pub album_id: Option<String>,
    pub art_url: Option<String>,
    pub art_small: Option<String>,
    pub duration_ms: u32,
    pub position_ms: u32,
    pub playing: bool,
    pub loading: bool,
    pub shuffle: bool,
    pub repeat: RepeatMode,
    pub volume_percent: u8,
    pub can_control: bool,
    /// Whether TIDAL lets this app change the device's volume. A phone
    /// playing over Bluetooth, for one, reports that it does not.
    pub can_set_volume: bool,
    /// The remembered song from the last session, shown paused before a
    /// first press. Nothing is playing yet.
    pub resuming: bool,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Target {
    Local,
    Remote(Option<String>),
}

struct PendingAlbumQueue {
    id: String,
    label: String,
    target: Target,
    offset: u32,
    tracks: Vec<Track>,
}

struct PendingQueueAdd {
    item: PlayableItem,
    at: Instant,
    /// Position in `manual_queue`, adjusted whenever an earlier row leaves.
    manual_index: usize,
    /// Remote write and position within it, until TIDAL accepts this copy.
    write: Option<(u64, usize)>,
}

/// Song links pasted into a playlist, in clipboard order, while some of
/// the songs are still being looked up.
struct PendingPaste {
    playlist_id: String,
    playlist_name: String,
    uris: Vec<String>,
    /// The songs known so far, by the pasted URI.
    found: HashMap<String, PlayableItem>,
    /// Links TIDAL had no song for, .
    missing: HashSet<String>,
}

impl PendingPaste {
    fn settled(&self) -> bool {
        self.uris
            .iter()
            .all(|uri| self.found.contains_key(uri) || self.missing.contains(uri))
    }
}

/// An automatic update step put off on a metered connection or without
/// internet, taken once the connection is neither.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum HeldUpdate {
    /// Look at how this copy was installed, to see if it can update itself.
    Inspect,
    /// Download the release.
    Download,
}

/// How the application is being started.
#[derive(Clone, Copy, Debug)]
pub struct AppOptions {
    /// Demo and isolated tests must not read or migrate real TIDAL grants.
    pub restore_sign_in: bool,
    /// Register the MPRIS media-control service, follow the desktop's light
    /// or dark preference (Linux) and the system's power and session state.
    pub media_controls: bool,
    /// Register the system-tray item (Linux).
    pub tray: bool,
}

impl Default for AppOptions {
    fn default() -> Self {
        Self {
            restore_sign_in: true,
            media_controls: true,
            tray: true,
        }
    }
}

/// Listening time for the current track.
///
/// `listened` stores completed intervals. `playing_since` starts the current
/// interval and is `None` while paused.
/// The tray goes first, and on Linux carefully (see `tray_exit`).
impl Drop for App {
    fn drop(&mut self) {
        crate::tray_exit::release(self.tray.take());
    }
}

struct Listening {
    uri: String,
    listened: std::time::Duration,
    playing_since: Option<Instant>,
    recorded: bool,
}

