    /// Only controls show the hand: over the What's new dialog's text, and
    /// over the update popup's, the cursor stays the arrow.
    #[test]
    fn the_hand_cursor_stays_off_dialog_text() {
        fn cursor_at(app: &mut App, ctx: &egui::Context, at: egui::Pos2) -> egui::CursorIcon {
            let mut last = egui::CursorIcon::Default;
            for _ in 0..6 {
                let mut input = egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(1000.0, 800.0),
                    )),
                    ..Default::default()
                };
                input.events.push(egui::Event::PointerMoved(at));
                let mut output = ctx.run_ui(input, |ui| app.frame_ui(ui));
                output.textures_delta.clear();
                last = output.platform_output.cursor_icon;
            }
            last
        }
        let ctx = egui::Context::default();
        let mut app = test_app("hand-off-dialog-text");
        app.attach(&ctx);
        crate::demo::populate(&mut app);
        app.dialog = Some(Dialog::WhatsNew { since: None });
        // Down the dialog's column, below its header row: text and gaps.
        // (Lower down sits the 1.0.1 notes' changelog link, which rightly
        // shows the hand: links in the notes open when clicked.)
        for y in [300.0, 380.0, 450.0] {
            assert_eq!(
                cursor_at(&mut app, &ctx, egui::pos2(500.0, y)),
                egui::CursorIcon::Default,
                "dialog at y={y}"
            );
        }
        app.dialog = None;
        app.update = Some(crate::updates::Release {
            version: "9.9.9".into(),
            url: "https://example.invalid/".into(),
        });
        app.show_update = true;
        for y in [350.0, 400.0, 450.0] {
            assert_eq!(
                cursor_at(&mut app, &ctx, egui::pos2(500.0, y)),
                egui::CursorIcon::Default,
                "popup at y={y}"
            );
        }
    }

    /// A narrow window takes width from the side panels before the top bar
    /// runs out of room (#624), and the widths the listener chose come back
    /// once the window widens. With the Queue open, the window's minimum
    /// grows to the panels' least widths and the page's.
    #[test]
    fn side_panels_give_the_top_bar_its_room_and_keep_their_widths() {
        fn draw(ctx: &egui::Context, app: &mut App, width: f32) -> Vec<egui::ViewportCommand> {
            let mut output = ctx.run_ui(
                egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(width, 700.0),
                    )),
                    ..Default::default()
                },
                |ui| app.frame_ui(ui),
            );
            output.textures_delta.clear();
            output
                .viewport_output
                .remove(&egui::ViewportId::ROOT)
                .map(|viewport| viewport.commands)
                .unwrap_or_default()
        }
        let panel = |ctx: &egui::Context, id: &str| {
            egui::containers::panel::PanelState::load(ctx, egui::Id::new(id))
                .unwrap()
                .size()
                .x
        };
        let ctx = egui::Context::default();
        let mut app = test_app("panels-give-way");
        app.attach(&ctx);
        crate::demo::populate(&mut app);
        app.settings.sidebar_width = 400.0;
        app.settings.lyrics_width = 500.0;
        app.show_lyrics_panel = true;

        let mut commands = Vec::new();
        for _ in 0..3 {
            commands.extend(draw(&ctx, &mut app, 1000.0));
        }
        let least = crate::ui::topbar::least_width(&ctx);
        let sidebar = panel(&ctx, "sidebar");
        let lyrics = panel(&ctx, "lyrics-panel");
        assert!(
            sidebar + lyrics + least <= 1000.5,
            "the page keeps {} of the {least} points its bar needs",
            1000.0 - sidebar - lyrics
        );
        assert!(sidebar >= 210.0 && lyrics >= crate::theme::SIDE_PANEL_MIN_WIDTH);
        assert_eq!(app.settings.sidebar_width, 400.0);
        assert_eq!(app.settings.lyrics_width, 500.0);
        let min = (210.0 + crate::theme::SIDE_PANEL_MIN_WIDTH + least).round();
        assert!(
            commands.iter().any(|command| matches!(
                command,
                egui::ViewportCommand::MinInnerSize(size) if size.x == min
            )),
            "the window's minimum makes room for the Lyrics: {commands:?}"
        );

        for _ in 0..2 {
            draw(&ctx, &mut app, 1800.0);
        }
        assert_eq!(panel(&ctx, "sidebar"), 400.0);
        assert_eq!(panel(&ctx, "lyrics-panel"), 500.0);

        // Closing the Lyrics gives the window its usual minimum back.
        app.show_lyrics_panel = false;
        let commands = draw(&ctx, &mut app, 1800.0);
        assert!(commands.iter().any(|command| matches!(
            command,
            egui::ViewportCommand::MinInnerSize(size)
                if size.x == crate::window::MAIN_MIN_SIZE[0]
        )));
    }

    /// SmallWindow (a plugin) takes the window's minimum size away: the
    /// window is told so once, and told its own minimum again when the
    /// plugin puts the limit back.
    #[test]
    fn a_plugin_can_lower_the_window_minimum_and_put_it_back() {
        fn draw(ctx: &egui::Context, app: &mut App) -> Vec<egui::ViewportCommand> {
            let mut output = ctx.run_ui(
                egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(1000.0, 700.0),
                    )),
                    ..Default::default()
                },
                |ui| app.frame_ui(ui),
            );
            output.textures_delta.clear();
            output
                .viewport_output
                .remove(&egui::ViewportId::ROOT)
                .map(|viewport| viewport.commands)
                .unwrap_or_default()
        }
        let minimums = |commands: &[egui::ViewportCommand]| {
            commands
                .iter()
                .filter_map(|c| match c {
                    egui::ViewportCommand::MinInnerSize(size) => Some(*size),
                    _ => None,
                })
                .collect::<Vec<_>>()
        };
        let ctx = egui::Context::default();
        let mut app = test_app("plugin-window-minimum");
        app.attach(&ctx);
        crate::demo::populate(&mut app);
        draw(&ctx, &mut app);

        crate::ui::set_plugin_min_size(&ctx, Some([0, 0]));
        let sent = minimums(&draw(&ctx, &mut app));
        assert_eq!(sent, vec![egui::Vec2::ZERO]);
        assert!(minimums(&draw(&ctx, &mut app)).is_empty(), "sent once");

        crate::ui::set_plugin_min_size(&ctx, None);
        let sent = minimums(&draw(&ctx, &mut app));
        assert_eq!(
            sent,
            vec![egui::vec2(
                crate::window::MAIN_MIN_SIZE[0],
                crate::window::MAIN_MIN_SIZE[1]
            )]
        );
    }

    /// Linux autoscrolls once the listener turns it on; macOS never does.
    #[test]
    fn middle_clicking_a_playlist_row_autoscrolls_on_linux_when_chosen() {
        middle_click_a_playlist_row(true);
    }

    /// Middle-clicks a real playlist row, moves over the queue, and checks
    /// that the list scrolls exactly where autoscroll is on, and that the
    /// click never plays the row. The window is 1000 high: beside the open
    /// queue the playlist's header stacks as in TIDAL and its rows start
    /// lower.
    fn middle_click_a_playlist_row(chosen: bool) {
        use egui::accesskit::Role;
        let on = crate::autoscroll::enabled(chosen);
        fn draw(
            ctx: &egui::Context,
            app: &mut App,
            time: u32,
            events: Vec<egui::Event>,
        ) -> egui::accesskit::TreeUpdate {
            let mut output = ctx.run_ui(
                egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(1280.0, 1000.0),
                    )),
                    time: Some(time as f64 / 60.0),
                    events,
                    ..Default::default()
                },
                |ui| app.frame_ui(ui),
            );
            output.textures_delta.clear();
            output.platform_output.accesskit_update.unwrap()
        }
        let ctx = egui::Context::default();
        ctx.enable_accesskit();
        let mut app = test_app(if chosen {
            "autoscroll-playlist-row-chosen"
        } else {
            "autoscroll-playlist-row"
        });
        app.attach(&ctx);
        crate::demo::populate(&mut app);
        app.settings.middle_click_autoscroll = chosen;
        app.open(Page::Playlist("pl1".into()));
        app.show_queue_panel = true;
        let playing = app.now_playing().unwrap().uri.clone();
        draw(&ctx, &mut app, 0, vec![]);
        let tree = draw(&ctx, &mut app, 1, vec![]);
        let (id, node) = tree
            .nodes
            .iter()
            .find(|(_, node)| {
                node.role() == Role::Button
                    && node
                        .label()
                        .is_some_and(|label| label.starts_with("Play ") && label.contains(','))
                    && node.bounds().is_some_and(|rect| {
                        rect.x0 > 250.0
                            && rect.x0 < 700.0
                            && rect.width() > 400.0
                            && rect.y0 > 60.0
                            && rect.y1 < 900.0
                    })
            })
            .expect("a visible playlist row");
        let id = *id;
        let before = node.bounds().unwrap();
        let anchor = egui::pos2(before.x0 as f32 + 120.0, before.y0 as f32 + 12.0);
        draw(
            &ctx,
            &mut app,
            2,
            vec![
                egui::Event::PointerMoved(anchor),
                egui::Event::PointerButton {
                    pos: anchor,
                    button: egui::PointerButton::Middle,
                    pressed: true,
                    modifiers: egui::Modifiers::NONE,
                },
            ],
        );
        assert_eq!(
            app.autoscroll.active(),
            on,
            "only an enabled autoscroll arms the real row's scroll area"
        );
        draw(
            &ctx,
            &mut app,
            3,
            vec![egui::Event::PointerButton {
                pos: anchor,
                button: egui::PointerButton::Middle,
                pressed: false,
                modifiers: egui::Modifiers::NONE,
            }],
        );
        for frame in 4..8 {
            draw(
                &ctx,
                &mut app,
                frame,
                vec![egui::Event::PointerMoved(egui::pos2(
                    1100.0,
                    anchor.y + 100.0,
                ))],
            );
        }
        let tree = draw(&ctx, &mut app, 8, vec![]);
        let after = tree
            .nodes
            .iter()
            .find(|(node_id, _)| *node_id == id)
            .expect("the same displayed occurrence")
            .1
            .bounds()
            .unwrap();
        if on {
            assert!(
                after.y0 < before.y0,
                "the playlist must scroll while the pointer is over Queue"
            );
        } else {
            assert_eq!(after.y0, before.y0, "middle-click must not move the list");
        }
        assert_eq!(app.now_playing().unwrap().uri, playing);
        assert_eq!(app.autoscroll.active(), on);
    }

    /// A press on a link or a button inside a row starts autoscroll like
    /// one on the row itself: none of them uses the middle button.
    #[test]
    fn middle_clicking_a_link_or_button_in_a_playlist_row_autoscrolls() {
        use egui::accesskit::Role;
        let on = crate::autoscroll::enabled(true);
        fn draw(
            ctx: &egui::Context,
            app: &mut App,
            time: u32,
            events: Vec<egui::Event>,
        ) -> egui::accesskit::TreeUpdate {
            let mut output = ctx.run_ui(
                egui::RawInput {
                    screen_rect: Some(egui::Rect::from_min_size(
                        egui::Pos2::ZERO,
                        egui::vec2(1280.0, 800.0),
                    )),
                    time: Some(time as f64 / 60.0),
                    events,
                    ..Default::default()
                },
                |ui| app.frame_ui(ui),
            );
            output.textures_delta.clear();
            output.platform_output.accesskit_update.unwrap()
        }
        for (role, label) in [
            (Role::Link, None),
            (Role::Button, Some("Add to My Collection")),
            (Role::Button, Some("More")),
        ] {
            let ctx = egui::Context::default();
            ctx.enable_accesskit();
            let mut app = test_app("autoscroll-row-controls");
            app.attach(&ctx);
            crate::demo::populate(&mut app);
            app.settings.middle_click_autoscroll = true;
            app.open(Page::Playlist("pl1".into()));
            draw(&ctx, &mut app, 0, vec![]);
            let tree = draw(&ctx, &mut app, 1, vec![]);
            let control = tree
                .nodes
                .iter()
                .filter_map(|(_, node)| Some((node, node.bounds()?)))
                .find(|(node, rect)| {
                    node.role() == role
                        && label.is_none_or(|label| node.label() == Some(label))
                        && rect.x0 > 300.0
                        && rect.y0 > 300.0
                        && rect.y1 < 710.0
                })
                .map(|(_, rect)| egui::pos2(rect.x0 as f32 + 4.0, (rect.y0 + rect.y1) as f32 / 2.0))
                .unwrap_or_else(|| panic!("a visible {role:?} {label:?} in a row"));
            draw(&ctx, &mut app, 2, vec![egui::Event::PointerMoved(control)]);
            draw(
                &ctx,
                &mut app,
                3,
                vec![egui::Event::PointerButton {
                    pos: control,
                    button: egui::PointerButton::Middle,
                    pressed: true,
                    modifiers: egui::Modifiers::NONE,
                }],
            );
            assert_eq!(app.autoscroll.active(), on, "{role:?} {label:?}");
            app.backend.shutdown();
        }
    }

    #[test]
    fn autoscroll_updates_the_real_lyrics_without_changing_playback() {
        for chosen in [false, true] {
            let on = crate::autoscroll::enabled(chosen);
            let ctx = egui::Context::default();
            let mut app = test_app(if chosen {
                "autoscroll-lyrics-chosen"
            } else {
                "autoscroll-lyrics"
            });
            app.attach(&ctx);
            crate::demo::populate(&mut app);
            app.settings.middle_click_autoscroll = chosen;
            app.show_queue_panel = false;
            app.show_lyrics_panel = true;
            app.lyrics = Loadable::Loaded(Some(crate::lyrics::Lyrics {
                lines: (0..80)
                    .map(|i| crate::lyrics::Line {
                        at_ms: Some(i * 5000),
                        text: format!("Autoscroll lyric line {i}"),
                    })
                    .collect(),
                synced: true,
                instrumental: false,
            }));
            if let Some(remote) = &mut app.remote {
                remote.state.is_playing = false;
                remote.state.progress_ms = Some(0);
            }
            let playing = app.now_playing().unwrap().uri.clone();
            let mut frame = 0;
            let mut draw = |app: &mut App, events: Vec<egui::Event>| {
                frame += 1;
                let mut output = ctx.run_ui(
                    egui::RawInput {
                        screen_rect: Some(egui::Rect::from_min_size(
                            egui::Pos2::ZERO,
                            egui::vec2(1280.0, 800.0),
                        )),
                        time: Some(frame as f64 / 60.0),
                        events,
                        ..Default::default()
                    },
                    |ui| app.frame_ui(ui),
                );
                output.textures_delta.clear();
            };
            draw(&mut app, vec![]);
            draw(&mut app, vec![]);
            let anchor = egui::pos2(1120.0, 100.0);
            let press = |button, pressed| egui::Event::PointerButton {
                pos: anchor,
                button,
                pressed,
                modifiers: egui::Modifiers::NONE,
            };
            draw(
                &mut app,
                vec![
                    egui::Event::PointerMoved(anchor),
                    press(egui::PointerButton::Middle, true),
                ],
            );
            assert_eq!(app.autoscroll.active(), on, "real surface");
            assert_eq!(app.lyrics_following, !on);
            draw(&mut app, vec![press(egui::PointerButton::Middle, false)]);
            for _ in 0..5 {
                draw(
                    &mut app,
                    vec![egui::Event::PointerMoved(anchor + egui::vec2(0.0, 120.0))],
                );
            }
            assert_eq!(app.lyrics_following, !on);
            assert_eq!(app.now_playing().unwrap().uri, playing);
            draw(&mut app, vec![press(egui::PointerButton::Primary, true)]);
            assert!(!app.autoscroll.active());
            draw(&mut app, vec![press(egui::PointerButton::Primary, false)]);
            app.backend.shutdown();
        }
    }

    #[test]
    fn shift_wheel_moves_the_shelf_without_scrolling_the_page() {
        let mut app = headless_app();
        let ctx = egui::Context::default();
        theme::install(&ctx);
        let mut shelf_left = 0.0;
        let mut initial_left = 0.0;
        let mut page_offset = 0.0;
        for frame in 0..6 {
            let mut input = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(600.0, 400.0),
                )),
                time: Some(frame as f64 / 60.0),
                ..Default::default()
            };
            input
                .events
                .push(egui::Event::PointerMoved(egui::pos2(100.0, 70.0)));
            if frame == 2 {
                input.events.push(egui::Event::MouseWheel {
                    unit: egui::MouseWheelUnit::Line,
                    delta: egui::vec2(0.0, -3.0),
                    phase: egui::TouchPhase::Move,
                    modifiers: egui::Modifiers::SHIFT,
                });
            }
            let mut output = ctx.run_ui(input, |ui| {
                app.scrolling.apply(ui.ctx());
                let page = egui::ScrollArea::vertical().show(ui, |ui| {
                    crate::ui::widgets::shelf(
                        ui,
                        &app.palette,
                        "wheel-test-shelf",
                        "Shelf",
                        |ui| {
                            shelf_left = ui.allocate_space(egui::vec2(1600.0, 100.0)).1.left();
                        },
                    );
                    ui.allocate_space(egui::vec2(100.0, 1200.0));
                });
                page_offset = page.state.offset.y;
            });
            output.textures_delta.clear();
            if frame == 0 {
                initial_left = shelf_left;
            }
        }
        assert!(shelf_left < initial_left, "Shift+wheel must move the shelf");
        assert_eq!(page_offset, 0.0, "the enclosing page must stay put");
    }

    /// A song started outside a playlist must turn off the playlist's
    /// sidebar light at once, even while TIDAL still reports the old
    /// context from before the click.
    #[test]
    fn a_plain_song_clears_the_sidebar_context() {
        let ctx = egui::Context::default();
        let mut app = headless_app();
        app.assumed_context = Some(AssumedContext {
            uri: "tidal:playlist:sidebar".into(),
            shuffle: None,
            at: Instant::now(),
        });
        app.remote = Some(RemoteSnapshot {
            state: PlaybackState {
                context: Some(crate::api::models::Context {
                    uri: "tidal:playlist:sidebar".into(),
                    ..Default::default()
                }),
                is_playing: true,
                ..Default::default()
            },
            received_at: Instant::now(),
        });

        app.apply(
            Action::PlayUris {
                uris: vec!["tidal:track:standalone".into()],
                index: 0,
            },
            &ctx,
        );

        assert_eq!(app.playing_context_uri(), None);
    }

    /// The playlist just started stays lit after the first seconds even
    /// while the last poll, taken before the click, still names what the
    /// phone was playing; only a poll from after the click may say
    /// otherwise.
    #[test]
    fn a_poll_from_before_the_click_does_not_move_the_sidebar_light() {
        // #given a poll from the phone's playlist, then a playlist started here
        let mut app = headless_app();
        app.remote = Some(RemoteSnapshot {
            state: PlaybackState {
                context: Some(crate::api::models::Context {
                    uri: "tidal:playlist:phone".into(),
                    ..Default::default()
                }),
                is_playing: true,
                ..Default::default()
            },
            received_at: Instant::now() - Duration::from_secs(30),
        });
        app.assumed_context = Some(AssumedContext {
            uri: "tidal:playlist:here".into(),
            shuffle: None,
            at: Instant::now() - ASSUMED_CONTEXT_HOLD - Duration::from_secs(1),
        });
        app.optimistic_playing = Some((true, Instant::now()));

        // #then the hold is over, yet the stale poll does not win
        assert_eq!(
            app.playing_context_uri().as_deref(),
            Some("tidal:playlist:here")
        );

        // #when a poll taken after the click still reports the phone's playlist
        app.remote.as_mut().expect("a snapshot").received_at = Instant::now();

        // #then TIDAL's word from after the click stands
        assert_eq!(
            app.playing_context_uri().as_deref(),
            Some("tidal:playlist:phone")
        );
    }

    /// A song the Web API had greyed out stays greyed out when the session
    /// reads the rows, at every place it recurs, whether the Web API's word
    /// came from an earlier page or from the disk cache of a visit the
    /// playlist has changed since. Rows it never described stay unknown,
    /// and a song it later calls playable is no longer greyed out.
    #[test]
    fn a_session_read_keeps_a_songs_known_unavailability() {
        let mut app = headless_app();
        app.user = Some(User {
            id: "alice".into(),
            ..Default::default()
        });
        let row = |uri: &str, is_playable: Option<bool>| crate::api::models::PlaylistItem {
            item: Some(PlayableItem::Track(Track {
                uri: uri.into(),
                is_playable,
                ..Default::default()
            })),
            ..Default::default()
        };
        let items =
            |id: &str, rows: Vec<crate::api::models::PlaylistItem>| ApiResponse::PlaylistItems {
                id: id.into(),
                offset: 0,
                generation: 0,
                result: Ok(crate::api::models::Page {
                    total: rows.len() as u32,
                    limit: 50,
                    items: rows,
                    ..Default::default()
                }),
            };
        let rows = |app: &App, id: &str| {
            app.playlist_pages[id]
                .items
                .items
                .iter()
                .map(|item| match item.playable() {
                    Some(PlayableItem::Track(track)) => track.is_playable,
                    _ => None,
                })
                .collect::<Vec<_>>()
        };

        // The Web API's word from an earlier page of the same list.
        app.playlist_pages
            .insert("pl1".into(), PlaylistPage::default());
        app.handle_api(items(
            "pl1",
            vec![
                row("tidal:track:gone", Some(false)),
                row("tidal:track:fine", Some(true)),
                row("tidal:track:gone", Some(false)),
            ],
        ));
        app.handle_api(items(
            "pl1",
            vec![
                row("tidal:track:gone", None),
                row("tidal:track:fine", None),
                row("tidal:track:new", None),
                row("tidal:track:gone", None),
            ],
        ));
        assert_eq!(rows(&app, "pl1"), [Some(false), None, None, Some(false)]);

        // The Web API's word from the disk cache of another visit, read
        // after the session page arrived and never adopted, the playlist
        // having changed since.
        app.playlist_pages.insert(
            "pl2".into(),
            PlaylistPage {
                playlist: Loadable::Loaded(Playlist {
                    id: "pl2".into(),
                    snapshot_id: Some("now".into()),
                    ..Default::default()
                }),
                ..Default::default()
            },
        );
        app.handle_api(items(
            "pl2",
            vec![
                row("tidal:track:other", None),
                row("tidal:track:fine", None),
            ],
        ));
        app.receive_playlist_cache(
            "alice",
            "pl2",
            0,
            Some(PlaylistCache {
                snapshot: "then".into(),
                items: vec![row("tidal:track:other", Some(false))],
                total: 1,
                next_offset: None,
                appendable: false,
            }),
        );
        assert_eq!(
            rows(&app, "pl2"),
            [Some(false), None],
            "the cache's word reaches the rows already shown"
        );
        assert!(
            app.playlist_pages["pl2"].pending_cache.is_none(),
            "though the stale cache itself is not adopted"
        );

        // A song the Web API later calls playable is no longer greyed out.
        app.handle_api(items("pl2", vec![row("tidal:track:other", Some(true))]));
        app.handle_api(items("pl2", vec![row("tidal:track:other", None)]));
        assert_eq!(rows(&app, "pl2"), [None]);
    }

    fn availability_row(playable: Option<bool>) -> PlaylistItem {
        PlaylistItem {
            item: Some(PlayableItem::Track(Track {
                uri: "tidal:track:availability".into(),
                is_playable: playable,
                ..Default::default()
            })),
            ..Default::default()
        }
    }

    fn receive_availability_rows(app: &mut App, id: &str, playable: Option<bool>) {
        app.playlist_pages
            .entry(id.into())
            .or_insert_with(|| PlaylistPage {
                playlist: Loadable::Loaded(Playlist {
                    id: id.into(),
                    snapshot_id: Some("now".into()),
                    ..Default::default()
                }),
                ..Default::default()
            });
        app.handle_api(ApiResponse::PlaylistItems {
            id: id.into(),
            offset: 0,
            generation: 0,
            result: Ok(crate::api::models::Page {
                items: vec![availability_row(playable)],
                total: 1,
                limit: 50,
                ..Default::default()
            }),
        });
    }

    fn shown_availability(app: &mut App, id: &str) -> Option<bool> {
        let page = &app.playlist_pages[id];
        let generation = page.generation;
        let revision = page.items.revision;
        let rows = page
            .items
            .items
            .iter()
            .filter_map(|row| row.playable().cloned().map(|item| (item, None, None)))
            .collect();
        let rows = crate::ui::collection::cached_table_items(
            app,
            Page::Playlist(id.into()),
            generation,
            revision,
            app.user_names_revision,
            || rows,
        );
        let PlayableItem::Track(track) = &rows[0].0;
        track.is_playable
    }

    fn old_availability_cache(playable: bool) -> Option<PlaylistCache> {
        Some(PlaylistCache {
            snapshot: "then".into(),
            items: vec![availability_row(Some(playable))],
            total: 1,
            next_offset: None,
            appendable: false,
        })
    }

