    /// An app started on a session file written beforehand, in its own
    /// temporary directory.
    fn app_with_session(name: &str, session: &SessionState) -> App {
        let root = crate::paths::unique_test_dir(&format!("session-restore-{name}"));
        let _ = std::fs::remove_dir_all(&root);
        let dirs = AppDirs {
            config: root.join("config"),
            state: root.join("state"),
            cache: root.join("cache"),
        };
        session.save(&dirs.session_file());
        App::new(
            &Waker::default(),
            dirs,
            Settings::default(),
            AppOptions {
                media_controls: false,
                restore_sign_in: false,
                tray: false,
            },
        )
    }

    fn finish_session_app(mut app: App) {
        app.backend.shutdown();
        let _ = std::fs::remove_dir_all(app.dirs.config.parent().unwrap());
    }

    fn remembered_session() -> SessionState {
        SessionState {
            last_page: Some("liked".into()),
            last_context: Some("tidal:playlist:pl1".into()),
            last_track: Some("tidal:track:two".into()),
            last_position_ms: 83_000,
            last_added_queue: vec!["tidal:track:q1".into(), "tidal:video:v9".into()],
            shuffle_on: true,
            last_repeat: Some("context".into()),
            last_shuffle_order: vec!["tidal:track:five".into(), "tidal:track:three".into()],
            volume_before_mute: Some(40),
            now_playing_open: Some(true),
            queue_open: Some(true),
            ..SessionState::default()
        }
    }

    /// Everything the session holds comes back at start, and closing again
    /// without playing keeps all of it.
    #[test]
    fn the_whole_session_round_trips_through_a_restart() {
        use crate::api::models::Track;
        let session = remembered_session();
        let mut app = app_with_session("round-trip", &session);
        assert_eq!(app.resume_context.as_deref(), Some("tidal:playlist:pl1"));
        assert_eq!(app.resume_track.as_deref(), Some("tidal:track:two"));
        assert_eq!(app.resume_position_ms, 83_000);
        assert_eq!(app.resume_queue, session.last_added_queue);
        assert!(app.shuffle_wanted);
        assert_eq!(app.resume_repeat, Some(RepeatMode::Context));
        assert_eq!(app.resume_order, session.last_shuffle_order);
        assert_eq!(app.volume_before_mute, Some(40));
        assert!(app.now_playing_view && app.show_queue_panel);

        // The paused song in the player bar carries the repeat mode, and the
        // queue panel names where it came from.
        app.track_cache.insert(
            "two".into(),
            Track {
                id: Some("two".into()),
                uri: "tidal:track:two".into(),
                name: "Two".into(),
                duration_ms: 200_000,
                ..Default::default()
            },
        );
        let now = app.now_playing().expect("the remembered song shows");
        assert!(now.resuming && !now.playing && now.shuffle);
        assert_eq!(now.repeat, RepeatMode::Context);
        assert_eq!(now.position_ms, 83_000);
        assert_eq!(
            app.playing_context_uri().as_deref(),
            Some("tidal:playlist:pl1")
        );

        // A second close with nothing played in between loses nothing.
        app.save_session();
        app.flush_writes();
        let again = SessionState::load(&app.dirs.session_file());
        assert_eq!(again.last_context, session.last_context);
        assert_eq!(again.last_track, session.last_track);
        assert_eq!(again.last_position_ms, 83_000);
        assert_eq!(again.last_added_queue, session.last_added_queue);
        assert_eq!(again.last_repeat, session.last_repeat);
        assert_eq!(again.last_shuffle_order, session.last_shuffle_order);
        assert_eq!(again.volume_before_mute, Some(40));
        assert_eq!(again.now_playing_open, Some(true));
        assert!(again.shuffle_on);
        finish_session_app(app);
    }

    /// The view is not reopened with nothing to show in it.
    #[test]
    fn now_playing_stays_closed_without_a_remembered_song() {
        let session = SessionState {
            now_playing_open: Some(true),
            ..SessionState::default()
        };
        let app = app_with_session("no-song-view", &session);
        assert!(!app.now_playing_view);
        finish_session_app(app);
    }

    /// A press of play resumes the saved song at the saved position, in its
    /// context, with the saved shuffled order, and applies the saved repeat.
    #[test]
    fn play_resumes_at_the_saved_position_with_the_saved_order() {
        let mut app = app_with_session("resume-play", &remembered_session());
        app.queued_play = None;
        assert!(app.resume_last());
        let request = app.queued_play.clone().expect("held for the engine");
        assert_eq!(request.context_uri.as_deref(), Some("tidal:playlist:pl1"));
        assert_eq!(request.offset_uri.as_deref(), Some("tidal:track:two"));
        assert_eq!(request.position_ms, 83_000);
        assert_eq!(
            request.shuffle_order,
            ["tidal:track:five", "tidal:track:three"]
        );
        let load = local_load(&request, true);
        assert_eq!(load.position_ms, 83_000);
        assert_eq!(load.order, request.shuffle_order);
        finish_session_app(app);
    }

    /// A remembered song TIDAL no longer has moves on to the next one in its
    /// context, or is forgotten when it has none, with a toast either way.
    #[test]
    fn a_remembered_song_that_is_gone_is_skipped_with_a_toast() {
        let session = SessionState {
            last_track: Some("tidal:track:gone".into()),
            last_position_ms: 5_000,
            ..SessionState::default()
        };
        let mut app = app_with_session("gone-track", &session);
        app.resume_track_gone("tidal:track:gone", "Gone Song");
        assert_eq!(app.resume_track, None);
        assert_eq!(app.resume_position_ms, 0);
        assert!(!app.toasts.is_empty());
        assert!(app.session_dirty);

        // Another song's answer changes nothing.
        app.resume_track = Some("tidal:track:here".into());
        app.toasts.clear();
        app.resume_track_gone("tidal:track:gone", "Gone Song");
        assert_eq!(app.resume_track.as_deref(), Some("tidal:track:here"));
        assert!(app.toasts.is_empty());
        finish_session_app(app);
    }

    /// Every kind of context restores its queue: one the engine can read
    /// again is read again, with the saved queue behind it should TIDAL not
    /// give it back; any other plays the saved queue as a list under the
    /// context's name. Either way Next goes on to the saved next song.
    #[test]
    fn every_kind_of_context_resumes_its_queue() {
        let upcoming: Vec<String> = ["tidal:track:11", "tidal:video:12", "tidal:track:13"]
            .iter()
            .map(|uri| uri.to_string())
            .collect();
        let saved: Vec<String> = std::iter::once("tidal:track:10".to_string())
            .chain(upcoming.iter().cloned())
            .collect();
        let readable = [
            "tidal:toptracks:art1",
            "tidal:artist:art1",
            "tidal:album:alb1",
            "tidal:playlist:pl1",
            "tidal:mix:mix1",
            "tidal:collection",
            "tidal:station:artist:art1",
            "tidal:offline",
        ];
        let lists = [
            "tidal:search:cats",
            "tidal:videos:art1",
            "tidal:similarvideos:vid1",
            "tidal:track:10",
            "tidal:somethingnew:1",
        ];
        for (n, context) in readable.iter().chain(lists.iter()).enumerate() {
            let session = SessionState {
                last_context: Some(context.to_string()),
                last_track: Some("tidal:track:10".into()),
                last_position_ms: 42_000,
                last_upcoming: upcoming.clone(),
                ..SessionState::default()
            };
            let mut app = app_with_session(&format!("ctx-{n}"), &session);
            assert!(app.resume_last(), "{context}");
            let request = app.queued_play.clone().expect("held for the engine");
            assert_eq!(request.position_ms, 42_000, "{context}");
            assert_eq!(request.offset_uri.as_deref(), Some("tidal:track:10"));
            if readable.contains(context) {
                assert_eq!(request.context_uri.as_deref(), Some(*context));
                assert_eq!(request.fallback_uris, saved, "{context}");
            } else {
                assert_eq!(request.context_uri, None, "{context}");
                assert_eq!(request.uris, saved, "{context}");
                assert_eq!(
                    app.assumed_context.as_ref().map(|a| a.uri.as_str()),
                    Some(*context)
                );
            }
            let load = local_load(&request, false);
            assert_eq!(load.fallback, request.fallback_uris);
            finish_session_app(app);
        }
    }

    /// Next before anything plays steps to the saved next song of a context
    /// only the engine can read, and the queue is saved again as it was.
    #[test]
    fn next_before_playing_steps_through_the_saved_queue() {
        let session = SessionState {
            last_context: Some("tidal:toptracks:art1".into()),
            last_track: Some("tidal:track:10".into()),
            last_upcoming: vec!["tidal:track:11".into(), "tidal:track:12".into()],
            shuffle_on: true,
            last_shuffle_order: vec!["tidal:track:11".into(), "tidal:track:12".into()],
            ..SessionState::default()
        };
        let mut app = app_with_session("next-resume", &session);
        assert!(app.step_resume(true));
        assert_eq!(app.resume_track.as_deref(), Some("tidal:track:11"));
        app.save_session();
        app.flush_writes();
        let saved = SessionState::load(&app.dirs.session_file());
        assert_eq!(saved.last_context.as_deref(), Some("tidal:toptracks:art1"));
        assert_eq!(saved.last_track.as_deref(), Some("tidal:track:11"));
        assert_eq!(saved.last_upcoming, ["tidal:track:12"]);
        assert_eq!(saved.last_shuffle_order, ["tidal:track:12"]);
        finish_session_app(app);
    }

    /// The upcoming songs are saved from the live queue, past the ones
