    /// The session is written behind the interface, and what was saved is
    /// on disk once the app has saved its state to quit.
    #[test]
    fn saving_the_state_to_quit_waits_for_the_session_write() {
        let mut app = app_with_session("quit-flush", &SessionState::default());
        let path = app.dirs.session_file();
        app.resume_track = Some("tidal:track:quit".into());
        app.save_state();
        assert_eq!(
            SessionState::load(&path).last_track.as_deref(),
            Some("tidal:track:quit")
        );
        finish_session_app(app);
    }

    /// Marking the session changed does not write at once: writes are held
    /// back so a burst of changes is one file write.
    #[test]
    fn session_writes_are_debounced() {
        let mut app = app_with_session("debounce", &SessionState::default());
        let path = app.dirs.session_file();
        app.resume_track = Some("tidal:track:x".into());
        app.session_dirty = true;
        app.last_session_save = Instant::now();
        let ctx = egui::Context::default();
        let pass = |app: &mut App| {
            let mut output = ctx.run_ui(egui::RawInput::default(), |ui| {
                app.background_frame(ui.ctx());
            });
            output.textures_delta.clear();
        };
        pass(&mut app);
        assert!(app.session_dirty, "held back inside the debounce window");
        assert_eq!(SessionState::load(&path).last_track, None);

        app.last_session_save = Instant::now() - Duration::from_secs(3);
        pass(&mut app);
        assert!(!app.session_dirty);
        app.flush_writes();
        assert_eq!(
            SessionState::load(&path).last_track.as_deref(),
            Some("tidal:track:x")
        );
        finish_session_app(app);
    }

    /// The song the last session ended on is shown, paused, at the position
    /// it stopped at, so a cold start does not look like an empty player.
    #[test]
    fn the_remembered_song_is_shown_paused_at_its_position() {
        use crate::api::models::{Album, ArtistRef, Track};
        let mut app = headless_app();
        app.resume_track = Some("tidal:track:abc".into());
        app.resume_position_ms = 19_566;
        assert!(
            app.now_playing().is_none(),
            "nothing to show until the song's details arrive"
        );
        app.track_cache.insert(
            "abc".into(),
            Track {
                id: Some("abc".into()),
                uri: "tidal:track:abc".into(),
                name: "Karma Police".into(),
                artists: vec![ArtistRef {
                    id: None,
                    name: "Radiohead".into(),
                    uri: None,
                    picture: None,
                }],
                album: Some(Album {
                    id: "ok".into(),
                    name: "OK Computer".into(),
                    ..Default::default()
                }),
                duration_ms: 264_000,
                ..Default::default()
            },
        );
        let now = app.now_playing().expect("the remembered song is shown");
        assert!(now.resuming);
        assert!(!now.playing, "it is shown paused, not played");
        assert_eq!(now.title, "Karma Police");
        assert_eq!(now.subtitle, "Radiohead");
        assert_eq!(now.album_name, "OK Computer");
        assert_eq!(now.duration_ms, 264_000);
        assert_eq!(
            now.position_ms, 19_566,
            "the bar sits where the listener left it, not at zero"
        );
    }

    /// Drawing the remembered song must not be mistaken for a song that
