    /// Clear queue removes manual rows and preserves matching context rows.
    #[test]
    fn clear_queue_takes_the_hand_queued_rows_and_keeps_the_context() {
        let ctx = egui::Context::default();
        let mut app = headless_app();
        app.local.track = Some(crate::player::LocalTrack {
            uri: "tidal:track:a".into(),
            ..Default::default()
        });
        app.local.playback = Playback::Playing;
        app.manual_queue = vec!["tidal:track:b".into(), "tidal:track:c".into()];
        app.queue = loaded_queue(
            "tidal:track:a",
            &[
                "tidal:track:b",
                "tidal:track:c",
                "tidal:track:c",
                "tidal:track:d",
            ],
        );
        assert!(app.can_clear_queue());
        app.apply(Action::ClearQueue, &ctx);
        let (_, next) = queue_uris(&app);
        assert_eq!(
            next,
            vec!["tidal:track:c", "tidal:track:d"],
            "one queued c goes, the context's own c stays"
        );
        assert!(app.manual_queue.is_empty());
        assert!(
            app.queue_recheck_at.is_some(),
            "a fetch follows to sweep rows queued from other devices"
        );
    }

    /// Rule: clearing takes back the rows Add to queue added, and the
    /// context's own copy of the same song is not one of them, however
    /// recently the song was queued.
    #[test]
    fn clearing_a_just_queued_song_leaves_the_contexts_copy_of_it() {
        let ctx = egui::Context::default();
        let mut app = headless_app();
        app.local.track = Some(crate::player::LocalTrack {
            uri: "tidal:track:a".into(),
            ..Default::default()
        });
        app.local.playback = Playback::Playing;
        // What is playing comes to b on its own later on.
        app.queue = loaded_queue(
            "tidal:track:a",
            &["tidal:track:ctx1", "tidal:track:b", "tidal:track:ctx2"],
        );
        app.apply(
            Action::AddToQueue {
                uri: "tidal:track:b".into(),
                label: "b".into(),
            },
            &ctx,
        );
        let (_, next) = queue_uris(&app);
        assert_eq!(
            next,
            vec![
                "tidal:track:b",
                "tidal:track:ctx1",
                "tidal:track:b",
                "tidal:track:ctx2",
            ],
            "one row queued on top, the context's own b still below"
        );
        assert!(app.can_clear_queue());
        app.apply(Action::ClearQueue, &ctx);
        let (_, next) = queue_uris(&app);
        assert_eq!(
            next,
            vec!["tidal:track:ctx1", "tidal:track:b", "tidal:track:ctx2",],
            "the queued b goes and the context keeps the b it was going to play"
        );
    }

    /// A playlist or mix dropped on the queue whose page was never opened
    /// (or is only partly read) is fetched whole and goes to the top of
    /// Next up; it used to add nothing, or only the rows read so far.
    #[test]
    fn play_next_fetches_a_playlist_not_loaded_here() {
        let ctx = egui::Context::default();
        let mut app = headless_app();
        app.local.track = Some(crate::player::LocalTrack {
            uri: "tidal:track:a".into(),
            ..Default::default()
        });
        app.local.playback = Playback::Playing;
        app.queue = loaded_queue("tidal:track:a", &["tidal:track:ctx1"]);
        app.backend.take_queue_requests();
        for uri in ["tidal:playlist:far", "tidal:mix:far"] {
            app.apply(
                Action::PlayNextContext {
                    uri: uri.into(),
                    label: "Far away".into(),
                },
                &ctx,
            );
            assert!(
                matches!(
                    app.backend.take_queue_requests().as_slice(),
                    [ApiRequest::ContextQueueSongs { context_uri, .. }] if context_uri == uri
                ),
                "{uri} is fetched"
            );
        }
        assert_eq!(queue_uris(&app).1, ["tidal:track:ctx1"]);
        app.handle_api(ApiResponse::ContextQueueSongs {
            context_uri: "tidal:playlist:far".into(),
            label: "Far away".into(),
            result: Ok(vec![
                album_queue_track("x"),
                Track {
                    is_playable: Some(false),
                    ..album_queue_track("gone")
                },
                album_queue_track("y"),
            ]),
        });
        app.apply_actions(&ctx);
        assert_eq!(
            queue_uris(&app).1,
            ["tidal:track:x", "tidal:track:y", "tidal:track:ctx1"]
        );
        app.handle_api(ApiResponse::ContextQueueSongs {
            context_uri: "tidal:mix:far".into(),
            label: "Far away".into(),
            result: Err(crate::api::ApiError::RateLimited),
        });
        assert!(app.toasts.iter().any(|toast| toast.kind == ToastKind::Error
            && toast.message.starts_with("Couldn't add Far away to queue")));
        app.backend.shutdown();
    }

    /// Add to queue inserts after manual queue rows and before context rows.
    #[test]
    fn play_next_queues_after_the_songs_already_queued() {
        let ctx = egui::Context::default();
        let mut app = headless_app();
        app.local.track = Some(crate::player::LocalTrack {
            uri: "tidal:track:a".into(),
            ..Default::default()
        });
        app.local.playback = Playback::Playing;
        app.queue = loaded_queue("tidal:track:a", &["tidal:track:ctx1", "tidal:track:ctx2"]);
        app.apply(
            Action::AddToQueue {
                uri: "tidal:track:b".into(),
                label: "b".into(),
            },
            &ctx,
        );
        app.apply(
            Action::AddToQueue {
                uri: "tidal:track:c".into(),
                label: "c".into(),
            },
            &ctx,
        );
        let (_, next) = queue_uris(&app);
        assert_eq!(
            next,
            vec![
                "tidal:track:b",
                "tidal:track:c",
                "tidal:track:ctx1",
                "tidal:track:ctx2",
            ],
            "queued songs keep their order and stay ahead of the context"
        );
        assert_eq!(
            app.toasts.last().map(|toast| toast.message.as_str()),
            Some("c added to queue")
        );
    }

    fn album_queue_track(id: &str) -> Track {
        Track {
            uri: format!("tidal:track:{id}"),
            name: id.to_string(),
            ..Default::default()
        }
    }

    #[test]
    fn a_play_that_finds_nothing_leaves_the_bar_and_shuffle_as_they_were() {
        let mut app = headless_app();
        app.backend.set_offline(true);
        app.local.connected = true;
        app.local.track = Some(crate::player::LocalTrack {
            uri: "tidal:track:old".into(),
            ..Default::default()
        });
        app.local.playback = Playback::Paused;
        app.assumed_context = Some(AssumedContext {
            uri: "tidal:album:old".into(),
            shuffle: None,
            at: Instant::now() - ASSUMED_CONTEXT_HOLD * 2,
        });
        // Shuffle is on; a page's Play turns it off before it loads.
        app.shuffle_wanted = true;
        app.local.shuffle = true;
        app.play_in_order();
        assert!(!app.shuffle_wanted);
        app.backend.take_player_commands();
        app.play_request(PlayRequest::context("tidal:album:new"), false);
        assert_eq!(app.assumed_context.as_ref().unwrap().uri, "tidal:album:new");
        let mut failed = app.local.clone();
        failed.error = Some("There is nothing to play here".into());
        app.handle_local(failed);
        assert_eq!(
            app.assumed_context.as_ref().unwrap().uri,
            "tidal:album:old",
            "the context line goes back to the playing song's"
        );
        assert!(app.shuffle_wanted, "so does Shuffle");
        assert!(
            app.backend
                .take_player_commands()
                .contains(&PlayerCommand::Shuffle(true)),
            "the engine's Shuffle is put back too"
        );
        assert!(!app.play_pending("tidal:album:new"));
        app.backend.shutdown();
    }

    /// The network is down when the song shown (a restored session's) is
    /// played from an album: the engine waits for the network and says so
    /// once. The play stands (the album does not flicker back to the one
    /// before), and the message is the translated one, shown once however
    /// often the engine reports the wait.
    #[test]
    fn a_song_waiting_for_the_network_keeps_the_play_and_says_so_once() {
        let mut app = headless_app();
        app.backend.set_offline(true);
        app.local.connected = true;
        app.local.track = Some(crate::player::LocalTrack {
            uri: "tidal:track:new".into(),
            ..Default::default()
        });
        app.local.playback = Playback::Paused;
        app.play_request(
            PlayRequest::context("tidal:album:new").starting_at_uri("tidal:track:new"),
            false,
        );
        assert_eq!(app.assumed_context.as_ref().unwrap().uri, "tidal:album:new");
        let toasts = app.toasts.len();
        let mut waiting = app.local.clone();
        waiting.track_sequence += 1;
        waiting.playback = Playback::Loading;
        waiting.loading = true;
        waiting.error = Some(crate::tidal_engine::NETWORK_WAIT.into());
        app.handle_local(waiting.clone());
        app.handle_local(waiting);
        assert_eq!(
            app.assumed_context.as_ref().unwrap().uri,
            "tidal:album:new",
            "the play stands"
        );
        assert_eq!(app.toasts.len(), toasts + 1);
        let toast = app.toasts.last().unwrap();
        assert_eq!(
            toast.message,
            "No internet connection. Tidalfast will carry on when you're back online"
        );
        assert_eq!(toast.count, 1, "said once");
        assert_ne!(
            engine_error_text(Locale::Spanish, crate::tidal_engine::NETWORK_WAIT),
            crate::tidal_engine::NETWORK_WAIT,
            "translated"
        );
        app.backend.shutdown();
    }

    #[test]
    fn explicit_and_ai_off_keep_those_songs_out_of_an_albums_queue_adds() {
        let mut app = test_app("queue-content-settings");
        // Both start allowed; the test turns them off.
        app.settings.allow_ai = true;
        let tracks = || {
            vec![
                Track {
                    explicit: true,
                    ..album_queue_track("explicit")
                },
                Track {
                    ai: true,
                    ..album_queue_track("ai")
                },
                album_queue_track("plain"),
            ]
        };
        app.queue_album_tracks(tracks(), "Album".into());
        assert_eq!(app.manual_queue.len(), 3, "everything plays by default");
        app.manual_queue.clear();
        app.settings.allow_explicit = false;
        app.queue_album_tracks(tracks(), "Album".into());
        assert_eq!(
            app.manual_queue,
            ["tidal:track:ai", "tidal:track:plain"],
            "explicit songs are not queued"
        );
        app.manual_queue.clear();
        app.settings.allow_ai = false;
        app.queue_album_tracks(tracks(), "Album".into());
        assert_eq!(app.manual_queue, ["tidal:track:plain"]);
        app.backend.shutdown();
    }

