        assert!(matches!(
            &requests[..],
            [ApiRequest::AlbumQueueTracks { offset: 0, .. }]
        ));
        let page = crate::api::models::Page {
            items: vec![album_queue_track("one"), album_queue_track("two")],
            offset: 0,
            limit: 2,
            total: 3,
            next: Some("next".into()),
        };
