    #[test]
    fn translated_context_labels_preserve_tidal_names() {
        use crate::i18n::Locale;
        use clap::ValueEnum;
        let mut app = headless_app();
        let today = jiff::Zoned::now().strftime("%Y-%m-%d").to_string();
        let title = "Home {date} 夜";
        app.track_cache.insert(
            "xyz".into(),
            crate::api::models::Track {
                id: Some("xyz".into()),
                uri: "tidal:track:xyz".into(),
                name: title.into(),
                ..Default::default()
            },
        );
        app.library.playlists = Loadable::Loaded(vec![crate::api::models::Playlist {
            id: "pl9".into(),
            uri: "tidal:playlist:pl9".into(),
            name: title.into(),
            ..Default::default()
        }]);
        for &locale in Locale::value_variants() {
            app.locale = locale;
            app.assumed_context = None;
            assert_eq!(
                app.queue_playlist_name(),
                gettext(locale, "Queue {date}").replace("{date}", &today)
            );
            for (uri, expected, page) in [
                (
                    "tidal:playlist:pl9",
                    title.into(),
                    Some(Page::Playlist("pl9".into())),
                ),
                (
                    "tidal:playlist:unloaded",
                    gettext(locale, "Playlist").into_owned(),
                    Some(Page::Playlist("unloaded".into())),
                ),
                (
                    "tidal:collection",
                    gettext(locale, "Tracks").into_owned(),
                    Some(Page::LikedSongs),
                ),
                (
                    "tidal:station:track:xyz",
                    gettext(locale, "{track} Radio").replace("{track}", title),
                    Some(Page::Radio("tidal:track:xyz".into())),
                ),
            ] {
                app.assumed_context = Some(AssumedContext {
                    uri: uri.into(),
                    shuffle: None,
                    at: Instant::now(),
                });
                let from = app.playing_from().unwrap();
                assert_eq!(from.name, expected);
                assert_eq!(from.page, page);
                if uri.starts_with("tidal:station:") {
                    assert_eq!(app.queue_playlist_name(), expected);
                }
            }
        }
    }

    /// The queue names where the playing song comes from and opens it.
    /// A radio has no page; a context whose name has not loaded is still
    /// named by kind so it can open.
    #[test]
    fn playing_from_names_the_context_and_its_page() {
        let mut app = headless_app();
        assert_eq!(app.playing_from(), None, "no context, no line");
        let assume = |app: &mut App, uri: &str| {
            app.assumed_context = Some(AssumedContext {
                uri: uri.into(),
                shuffle: None,
                at: Instant::now(),
            });
        };
        let named = |app: &App| {
            let from = app.playing_from().expect("a context is playing");
            (from.name, from.page)
        };

        app.library.playlists = Loadable::Loaded(vec![crate::api::models::Playlist {
            id: "pl9".into(),
            uri: "tidal:playlist:pl9".into(),
            name: "Long Way Home".into(),
            ..Default::default()
        }]);
        assume(&mut app, "tidal:playlist:pl9");
        assert_eq!(
            named(&app),
            ("Long Way Home".into(), Some(Page::Playlist("pl9".into())))
        );
        assume(&mut app, "tidal:playlist:unloaded");
        assert_eq!(
            named(&app),
            ("Playlist".into(), Some(Page::Playlist("unloaded".into())))
        );

        app.album_pages.insert(
            "alb1".into(),
            AlbumPage {
                album: Loadable::Loaded(crate::api::models::Album {
                    id: "alb1".into(),
                    uri: "tidal:album:alb1".into(),
                    name: "Black Sands".into(),
                    ..Default::default()
                }),
                ..Default::default()
            },
        );
        assume(&mut app, "tidal:album:alb1");
        assert_eq!(
            named(&app),
            ("Black Sands".into(), Some(Page::Album("alb1".into())))
        );

        assume(&mut app, "tidal:collection");
        assert_eq!(named(&app), ("Tracks".into(), Some(Page::LikedSongs)));

        app.track_cache.insert(
            "xyz".into(),
            crate::api::models::Track {
                id: Some("xyz".into()),
                uri: "tidal:track:xyz".into(),
                name: "Wish You Were Here".into(),
                ..Default::default()
            },
        );
        assume(&mut app, "tidal:station:track:xyz");
        assert_eq!(
            named(&app),
            (
                "Wish You Were Here Radio".into(),
                Some(Page::Radio("tidal:track:xyz".into()))
            )
        );
        assume(&mut app, "tidal:station:track:uncached");
        assert_eq!(
            named(&app),
            (
                "Radio".into(),
                Some(Page::Radio("tidal:track:uncached".into()))
            )
        );
        assume(&mut app, "tidal:station:playlist:pl9");
        assert_eq!(
            named(&app),
            (
                "Long Way Home Radio".into(),
                Some(Page::Radio("tidal:playlist:pl9".into()))
            )
        );
    }

    /// The Top Tracks page behind the artist page's "View all" loads a page
    /// at a time, ignores stale answers, and names its playing context.
    #[test]
    fn artist_top_tracks_page_paginates_and_names_its_context() {
        let mut app = headless_app();
        app.open(Page::ArtistTopTracks("art9".into()));
        assert_eq!(app.page(), &Page::ArtistTopTracks("art9".into()));
        app.artist_top_pages
            .entry("art9".into())
            .or_default()
            .tracks
            .loaded_once = false;
        let chunk = |offset: u32, count: u32, more: bool| crate::api::models::Page {
            items: (offset..offset + count)
                .map(|n| crate::api::models::Track {
                    id: Some(format!("t{n}")),
                    uri: format!("tidal:track:t{n}"),
                    name: format!("Song {n}"),
                    ..Default::default()
                })
                .collect(),
            total: 250,
            limit: 100,
            offset,
            next: more.then(|| "next".to_string()),
        };
        let answer = |offset, generation, result| ApiResponse::ArtistTopList {
            id: "art9".into(),
            offset,
            generation,
            result: Ok(result),
        };
        app.handle_api(answer(0, 0, chunk(0, 100, true)));
        assert_eq!(app.artist_top_pages["art9"].tracks.items.len(), 100);
        // A stale answer for another load changes nothing.
        app.handle_api(answer(100, 7, chunk(100, 100, true)));
        assert_eq!(app.artist_top_pages["art9"].tracks.items.len(), 100);
        app.artist_top_pages.get_mut("art9").unwrap().tracks.loading = false;
        app.load_more(Page::ArtistTopTracks("art9".into()));
        assert!(
            app.artist_top_pages["art9"].tracks.loading,
            "the next page is asked for"
        );
        app.handle_api(answer(100, 0, chunk(100, 100, true)));
        app.artist_top_pages.get_mut("art9").unwrap().tracks.loading = false;
        app.load_more(Page::ArtistTopTracks("art9".into()));
        app.handle_api(answer(200, 0, chunk(200, 50, false)));
        let list = &app.artist_top_pages["art9"].tracks;
        assert_eq!(list.items.len(), 250);
        assert!(list.is_complete(), "no further page after the last");

        app.artist_pages.insert(
            "art9".into(),
            ArtistPage {
                artist: Loadable::Loaded(crate::api::models::Artist {
                    id: "art9".into(),
                    name: "Bonobo".into(),
                    ..Default::default()
                }),
                ..Default::default()
            },
        );
        app.assumed_context = Some(AssumedContext {
            uri: "tidal:toptracks:art9".into(),
            shuffle: None,
            at: Instant::now(),
        });
        let from = app.playing_from().expect("a context is playing");
        assert_eq!(from.name, "Bonobo top tracks");
        assert_eq!(from.page, Some(Page::ArtistTopTracks("art9".into())));
        assert_eq!(
            Page::decode(&Page::ArtistTopTracks("art9".into()).encode()),
            Some(Page::ArtistTopTracks("art9".into()))
        );
    }

