    #[test]
    fn a_restored_video_is_read_by_id_and_shows_in_the_player_bar() {
        let mut app = headless_app();
        app.resume_track = Some("tidal:video:77".into());
        app.request_resume_track();
        assert!(
            app.track_requests.contains("video:77"),
            "the video is asked for by its id"
        );
        assert!(app.resume_preview().is_none(), "nothing to show yet");
        app.handle_api(ApiResponse::Video {
            id: "77".into(),
            result: Ok(crate::api::models::Video {
                id: "77".into(),
                name: "Restored Clip".into(),
                artist: "Someone".into(),
                duration: 200,
                images: Vec::new(),
                artists: Vec::new(),
                explicit: false,
                release_date: None,
            }),
        });
        assert!(!app.track_requests.contains("video:77"));
        let preview = app.resume_preview().expect("the video is shown paused");
        assert_eq!(preview.title, "Restored Clip");
        assert_eq!(preview.uri, "tidal:video:77");
        assert!(!preview.playing);
        // A video that is gone is skipped like a vanished song.
        app.resume_track = Some("tidal:video:78".into());
        app.resume_track_gone("tidal:video:78", "");
        assert_eq!(app.resume_track, None);
    }

    /// Rule: eight shelf pages and eight profiles are kept, the open one and
    /// any still loading among them and then the most recently opened; the
    /// rest are read again when opened.
    #[test]
    fn shelf_pages_and_profiles_are_capped_by_recent_use() {
        let mut app = headless_app();
        for i in 0..12 {
            let path = format!("pages/p{i}");
            app.touch_page(&Page::Shelf(path.clone()));
            app.shelf_pages.insert(path, Loadable::Loaded(Vec::new()));
            let id = format!("u{i}");
            app.touch_page(&Page::Profile(id.clone()));
            app.profiles
                .insert(id, Loadable::Loaded(crate::api::models::Profile::default()));
            std::thread::sleep(Duration::from_millis(2));
        }
        app.shelf_pages
            .insert("pages/busy".into(), Loadable::Loading);
        app.evict_stale_pages();
        assert_eq!(app.shelf_pages.len(), 8);
        assert!(app.shelf_pages.contains_key("pages/busy"), "still loading");
        assert!(app.shelf_pages.contains_key("pages/p11"));
        assert!(app.shelf_pages.contains_key("pages/p5"));
        assert!(!app.shelf_pages.contains_key("pages/p4"));
        assert_eq!(app.profiles.len(), 8);
        assert!(app.profiles.contains_key("u11"));
        assert!(!app.profiles.contains_key("u3"));
        assert!(!app.page_used.contains_key(&Page::Profile("u0".into())));
    }

