    #[test]
    fn a_new_release_opens_the_popup_once() {
        let release = |version: &str| crate::updates::Release {
            version: version.into(),
            url: format!("https://github.com/CIoudGuy/tidalfast/releases/tag/v{version}"),
        };
        for manual in [false, true] {
            let mut app = headless_app();
            let ctx = egui::Context::default();
            let check = |app: &mut App, version: &str| {
                app.handle_backend_events(vec![Event::UpdateChecked {
                    manual,
                    result: Ok(Some(release(version))),
                }]);
                app.apply_actions(&ctx);
            };
            check(&mut app, "1.2.3");
            assert!(app.update.is_some());
            assert!(app.show_update);
            // Later closes it, and the same release does not open it again.
            app.show_update = false;
            check(&mut app, "1.2.3");
            assert!(!app.show_update);
            check(&mut app, "1.2.4");
            assert!(app.show_update);
        }
    }

    #[test]
    fn the_first_start_after_an_update_says_so_once() {
        let mut app = headless_app();
        app.toasts.clear();
        app.settings.last_run_version.clear();
        // No record yet: nothing to compare with, so nothing is announced.
        app.note_version_change("0.13.0");
        assert!(app.toasts.is_empty());
        assert_eq!(app.settings.last_run_version, "0.13.0");
        assert!(app.settings_dirty);
        // Same version again: still quiet.
        app.settings_dirty = false;
        app.note_version_change("0.13.0");
        assert!(app.toasts.is_empty());
        assert!(!app.settings_dirty);
        // A newer one is announced with a What's new action.
        app.note_version_change("0.14.0");
        assert_eq!(app.toasts.len(), 1);
        assert_eq!(app.toasts[0].message, "Tidalfast updated to v0.14.0");
        assert!(matches!(
            app.toasts[0].action,
            Some((_, Action::ShowDialog(Dialog::WhatsNew { since: Some(_) })))
        ));
        assert_eq!(app.settings.last_run_version, "0.14.0");
        // A downgrade is recorded without a message.
        app.toasts.clear();
        app.note_version_change("0.13.0");
        assert!(app.toasts.is_empty());
        assert_eq!(app.settings.last_run_version, "0.13.0");
    }

