    /// Songs fetched for a dropped album show on the open playlist at once,
    /// and a failed fetch says so in plain words and adds nothing.
    #[test]
    fn dropped_album_songs_appear_on_the_open_playlist_immediately() {
        let mut app = headless_app();
        app.backend.set_offline(true);
        app.playlist_pages.insert(
            "target".into(),
            PlaylistPage {
                generation: 1,
                items_generation: 1,
                items: PagedList {
                    items: vec![cached_playlist_row("tidal:track:a")],
                    total: Some(1),
                    next_offset: None,
                    loaded_once: true,
                    ..Default::default()
                },
                ..Default::default()
            },
        );
        app.handle_api(ApiResponse::ContextSongs {
            playlist_id: "target".into(),
            playlist_name: "Mine".into(),
            result: Err(crate::api::ApiError::Network("offline".into())),
        });
        assert_eq!(app.playlist_pages["target"].items.items.len(), 1);
        assert!(app.toasts.iter().any(|toast| {
            toast.kind == ToastKind::Error && toast.message.starts_with("Playlist change failed")
        }));

        let track = |id: &str| Track {
            uri: format!("tidal:track:{id}"),
            ..Default::default()
        };
        app.handle_api(ApiResponse::ContextSongs {
            playlist_id: "target".into(),
            playlist_name: "Mine".into(),
            result: Ok(vec![track("x"), track("y")]),
        });
        let mut sent = app.backend.take_playlist_add_requests();
        if let [
            ApiRequest::CheckPlaylistDuplicates {
                playlist_id,
                playlist_name,
                items,
                position,
            },
        ] = sent.as_slice()
        {
            let (playlist_id, playlist_name, items, position) = (
                playlist_id.clone(),
                playlist_name.clone(),
                items.clone(),
                *position,
            );
            app.handle_api(ApiResponse::PlaylistDuplicatesChecked {
                playlist_id,
                playlist_name,
                items,
                position,
                result: Ok(vec![]),
            });
            sent = app.backend.take_playlist_add_requests();
        }
        assert!(matches!(
            sent.as_slice(),
            [ApiRequest::AddToPlaylist { uris, .. }] if uris.len() == 2
        ));
        assert_eq!(app.playlist_pages["target"].items.items.len(), 3);
    }

    #[test]
    fn positioned_playlist_additions_keep_partial_pages_and_ignore_old_reads() {
        for (base, position, scan_fails) in [
            (0, 1, false),
            (100, 101, false),
            (100, 102, true),
            (100, 50, false),
        ] {
            let mut app = headless_app();
            app.backend.set_offline(true);
            app.playlist_pages.insert(
                "target".into(),
                PlaylistPage {
                    generation: 9,
                    items_generation: 9,
                    items: PagedList {
                        base_offset: base,
                        items: vec![
                            cached_playlist_row("tidal:track:a"),
                            cached_playlist_row("tidal:track:b"),
                        ],
                        total: Some(200),
                        next_offset: Some(base + 2),
                        loaded_once: true,
                        ..Default::default()
                    },
                    ..Default::default()
                },
            );
            let item = cached_playlist_row("tidal:track:new")
                .playable()
                .unwrap()
                .clone();
            app.request_playlist_add("target".into(), "Target".into(), vec![item], Some(position));
            let mut sent = app.backend.take_playlist_add_requests();
            assert_eq!(sent.len(), 1);
            let ApiRequest::CheckPlaylistDuplicates {
                playlist_id,
                playlist_name,
                items,
                position: requested,
            } = sent.pop().unwrap()
            else {
                panic!("expected duplicate check");
            };
            assert_eq!(requested, Some(position));
            app.handle_api(ApiResponse::PlaylistDuplicatesChecked {
                playlist_id,
                playlist_name,
                items,
                position: requested,
                result: if scan_fails {
                    Err(crate::api::ApiError::Network("offline".into()))
                } else {
                    Ok(vec![])
                },
            });
            let page = &app.playlist_pages["target"];
            assert_eq!(page.items.total, Some(201));
            assert_eq!(page.items.next_offset, Some(base + 3));
            assert_eq!(
                page.items.base_offset,
                if position < base { base + 1 } else { base }
            );
            if position >= base {
                assert_eq!(page.items.items.len(), 3);
                assert_eq!(
                    page.items.items[(position - base) as usize]
                        .playable()
                        .unwrap()
                        .uri(),
                    "tidal:track:new"
                );
            } else {
                assert_eq!(page.items.items.len(), 2);
            }
            let held: Vec<_> = page
                .items
                .items
                .iter()
                .map(|row| row.playable().unwrap().uri().to_string())
                .collect();
            let sent = app.backend.take_playlist_add_requests();
            assert!(
                matches!(sent.as_slice(), [ApiRequest::AddToPlaylist { position: Some(at), .. }] if *at == position)
            );
            app.handle_api(ApiResponse::PlaylistItems {
                id: "target".into(),
                offset: base,
                generation: 9,
                result: Ok(crate::api::models::Page {
                    items: vec![cached_playlist_row("tidal:track:old")],
                    total: 200,
                    ..Default::default()
                }),
            });
            assert_eq!(
                app.playlist_pages["target"]
                    .items
                    .items
                    .iter()
                    .map(|row| row.playable().unwrap().uri().to_string())
                    .collect::<Vec<_>>(),
                held
            );
            app.handle_api(ApiResponse::PlaylistItemsChanged {
                id: "target".into(),
                message: String::new(),
                result: Ok(Some("new-snapshot".into())),
            });
            assert_eq!(
                app.playlist_pages["target"]
                    .items
                    .items
                    .iter()
                    .map(|row| row.playable().unwrap().uri().to_string())
                    .collect::<Vec<_>>(),
                held
            );
        }
    }

