    #[test]
    fn playlist_refresh_waits_for_all_writes_and_their_confirmed_snapshot() {
        let mut app = headless_app();
        app.backend.set_offline(true);
        app.playlist_pages.insert(
            "edited".into(),
            PlaylistPage {
                playlist: Loadable::Loaded(Playlist {
                    id: "edited".into(),
                    snapshot_id: Some("old".into()),
                    items_count: Some(TrackCount { total: 1 }),
                    ..Default::default()
                }),
                items: PagedList {
                    items: vec![cached_playlist_row("tidal:track:first")],
                    total: Some(1),
                    loaded_once: true,
                    ..Default::default()
                },
                ..Default::default()
            },
        );
        for uri in ["tidal:track:second", "tidal:track:third"] {
            app.add_to_playlist_now(
                "edited".into(),
                "Edited".into(),
                vec![cached_playlist_row(uri).playable().unwrap().clone()],
                None,
            );
        }
        let generation = app.playlist_pages["edited"].generation;
        app.reload(Page::Playlist("edited".into()));
        assert!(
            app.backend.take_playlist_item_requests().is_empty(),
            "refresh must not read the rows before the pending writes finish"
        );
        let metadata = |snapshot: &str, total| ApiResponse::Playlist {
            id: "edited".into(),
            generation,
            result: Ok(Playlist {
                id: "edited".into(),
                snapshot_id: Some(snapshot.into()),
                items_count: Some(TrackCount { total }),
                ..Default::default()
            }),
        };
        app.handle_api(ApiResponse::PlaylistItemsChanged {
            id: "edited".into(),
            message: String::new(),
            result: Ok(Some("first-write".into())),
        });
        app.handle_api(metadata("first-write", 2));
        assert_eq!(app.playlist_pages["edited"].items.total, Some(3));
        assert!(app.backend.take_playlist_item_requests().is_empty());
        app.handle_api(ApiResponse::PlaylistItemsChanged {
            id: "edited".into(),
            message: String::new(),
            result: Ok(Some("second-write".into())),
        });
        app.handle_api(metadata("first-write", 2));
        assert_eq!(app.playlist_pages["edited"].items.total, Some(3));
        assert!(app.backend.take_playlist_item_requests().is_empty());
        assert!(app.playlist_pages["edited"].items.loading);

        app.handle_api(metadata("second-write", 3));
        let refreshed_generation = app.playlist_pages["edited"].generation;
        assert!(refreshed_generation > generation);
        assert_eq!(
            app.backend.take_playlist_item_requests(),
            [("edited".into(), 0, refreshed_generation)]
        );
        let rows = |generation, uris: &[&str]| ApiResponse::PlaylistItems {
            id: "edited".into(),
            offset: 0,
            generation,
            result: Ok(crate::api::models::Page {
                total: uris.len() as u32,
                items: uris.iter().map(|uri| cached_playlist_row(uri)).collect(),
                ..Default::default()
            }),
        };
        app.handle_api(rows(generation, &["tidal:track:first"]));
        assert_eq!(app.playlist_pages["edited"].items.items.len(), 3);
        assert!(app.playlist_pages["edited"].items.loading);
        let expected = [
            "tidal:track:first",
            "tidal:track:second",
            "tidal:track:third",
            "tidal:track:added-elsewhere",
        ];
        app.handle_api(rows(refreshed_generation, &expected));
        let page = &app.playlist_pages["edited"];
        assert!(!page.items.loading);
        assert_eq!(
            page.items
                .items
                .iter()
                .map(|row| row.playable().unwrap().uri())
                .collect::<Vec<_>>(),
            expected
        );
    }

    #[test]
    fn playlist_window_reads_wait_for_an_optimistic_snapshot_to_be_confirmed() {
        for unconfirmed in [false, true] {
            let mut app = headless_app();
            app.backend.set_offline(true);
            app.playlist_pages.insert(
                "edited".into(),
                PlaylistPage {
                    generation: 7,
                    items: PagedList {
                        items: (0..50)
                            .map(|index| {
                                cached_playlist_row(&format!("tidal:track:edited_{index}"))
                            })
                            .collect(),
                        total: Some(1_000),
                        next_offset: Some(50),
                        loaded_once: true,
                        ..Default::default()
                    },
                    optimistic_snapshot: unconfirmed.then(|| "written".into()),
                    optimistic_positional: unconfirmed,
                    ..Default::default()
                },
            );
            app.load_window(Page::Playlist("edited".into()), 750);
            if unconfirmed {
                assert!(
                    app.backend.take_playlist_item_requests().is_empty(),
                    "a distant read would describe the old playlist snapshot"
                );
                let rows = &app.playlist_pages["edited"].items;
                assert_eq!(rows.base_offset, 0);
                assert_eq!(rows.items.len(), 50);
                assert_eq!(
                    rows.items[0].playable().unwrap().uri(),
                    "tidal:track:edited_0"
                );
                assert!(!rows.loading);
            } else {
                assert_eq!(
                    app.backend.take_playlist_item_requests(),
                    [("edited".into(), 750, 7)]
                );
            }
            app.backend.shutdown();
        }
    }

    fn stale_test_page(rows: usize, optimistic_total: u32, positional: bool) -> PlaylistPage {
        PlaylistPage {
            generation: 7,
            playlist: Loadable::Loaded(Playlist {
                id: "edited".into(),
                snapshot_id: Some("2000".into()),
                items_count: Some(TrackCount {
                    total: optimistic_total,
                }),
                ..Default::default()
            }),
            items: PagedList {
                items: (0..rows)
                    .map(|index| cached_playlist_row(&format!("tidal:track:old_{index}")))
                    .collect(),
                total: Some(optimistic_total),
                next_offset: Some(rows as u32),
                loaded_once: true,
                ..Default::default()
            },
            optimistic_snapshot: Some("2000".into()),
            optimistic_tail: if positional {
                Vec::new()
            } else {
                vec![cached_playlist_row("tidal:track:new")]
            },
            optimistic_positional: positional,
            snapshot_since: Some(Instant::now()),
            local_additions: ["tidal:track:new".into()].into(),
            ..Default::default()
        }
    }

    fn stale_header(snapshot: &str, total: u32) -> ApiResponse {
        ApiResponse::Playlist {
            id: "edited".into(),
            generation: 7,
            result: Ok(Playlist {
                id: "edited".into(),
                snapshot_id: Some(snapshot.into()),
                items_count: Some(TrackCount { total }),
                ..Default::default()
            }),
        }
    }

    fn server_rows(offset: u32, count: u32, total: u32) -> ApiResponse {
        ApiResponse::PlaylistItems {
            id: "edited".into(),
            offset,
            generation: 7,
            result: Ok(crate::api::models::Page {
                items: (offset..offset + count)
                    .map(|index| cached_playlist_row(&format!("tidal:track:old_{index}")))
                    .collect(),
                total,
                limit: count,
                offset,
                next: (offset + count < total).then(|| "more".to_string()),
            }),
        }
    }

    #[test]
    fn snapshots_compare_by_time_whatever_their_form() {
        assert!(snapshot_confirms(
            Some("2026-09-01T10:00:00.000+0000"),
            "1788256800000"
        ));
        assert!(snapshot_confirms(
            Some("2026-09-01T10:00:01.000+0000"),
            "1788256800000"
        ));
        assert!(!snapshot_confirms(
            Some("2026-09-01T09:59:59.000+0000"),
            "1788256800000"
        ));
        assert!(snapshot_confirms(Some("abc"), "abc"));
        assert!(!snapshot_confirms(None, "1"));
        assert!(same_snapshot(
            Some("2026-09-01T10:00:00.000+0000"),
            Some("1788256800000")
        ));
    }

    #[test]
    fn a_lagging_playlist_header_never_blanks_the_page_and_is_asked_again() {
        let mut app = headless_app();
        app.backend.set_offline(true);
        app.playlist_pages
            .insert("edited".into(), stale_test_page(3, 4, false));
        for _ in 0..8 {
            app.handle_api(stale_header("1000", 3));
            let page = &app.playlist_pages["edited"];
            assert!(page.items.error.is_none(), "the list is never replaced");
            assert_eq!(page.items.items.len(), 3);
            assert!(!page.items.loading);
            assert!(page.snapshot_retry_at.is_some(), "asked again later");
            assert!(page.optimistic_snapshot.is_some());
        }
        // TIDAL catches up, in the form its own header uses.
        app.handle_api(stale_header("1970-01-01T00:00:02.000+0000", 4));
        let page = &app.playlist_pages["edited"];
        assert_eq!(page.optimistic_snapshot, None);
        assert!(page.optimistic_tail.is_empty());
        assert!(page.snapshot_retry_at.is_none());
        assert!(page.items.error.is_none());
    }

    #[test]
    fn pagination_loads_every_page_while_tidal_lags_behind_an_added_song() {
        let mut app = headless_app();
        app.backend.set_offline(true);
        // 120 songs on TIDAL, one just added at the end: 121 shown.
        app.playlist_pages
            .insert("edited".into(), stale_test_page(50, 121, false));
        for step in 0..8 {
            app.handle_api(stale_header("1000", 120));
            let page = &app.playlist_pages["edited"];
            assert!(page.items.error.is_none(), "step {step}");
        }
        app.load_more(Page::Playlist("edited".into()));
        assert_eq!(
            app.backend.take_playlist_item_requests(),
            [("edited".into(), 50, 7)],
            "the second page is asked for while the answer lags"
        );
        app.handle_api(server_rows(50, 50, 120));
        let page = &app.playlist_pages["edited"];
        assert_eq!(page.items.items.len(), 100);
        assert_eq!(page.items.total, Some(121));
        assert_eq!(page.items.next_offset, Some(100));
        app.load_more(Page::Playlist("edited".into()));
        assert_eq!(
            app.backend.take_playlist_item_requests(),
            [("edited".into(), 100, 7)]
        );
        app.handle_api(server_rows(100, 20, 120));
        let page = &app.playlist_pages["edited"];
        assert_eq!(page.items.items.len(), 121, "TIDAL's rows and the new song");
        assert_eq!(
            page.items.items[120].playable().unwrap().uri(),
            "tidal:track:new"
        );
        assert_eq!(page.items.total, Some(121));
        assert_eq!(page.items.next_offset, None);
        assert!(page.items.error.is_none());
        // Once TIDAL agrees the overlay goes, and the list stays whole.
        app.handle_api(stale_header("1970-01-01T00:00:02.000+0000", 121));
        let page = &app.playlist_pages["edited"];
        assert_eq!(page.optimistic_snapshot, None);
        assert_eq!(page.items.items.len(), 121);
    }

    #[test]
    fn rows_read_while_a_reshaping_write_is_unconfirmed_wait_without_stalling() {
        let mut app = headless_app();
        app.backend.set_offline(true);
        app.playlist_pages
            .insert("edited".into(), stale_test_page(50, 120, true));
        app.playlist_pages.get_mut("edited").unwrap().items.loading = true;
        app.handle_api(server_rows(50, 50, 120));
        let page = &app.playlist_pages["edited"];
        assert_eq!(page.items.items.len(), 50, "an old read is not mixed in");
        assert!(!page.items.loading, "the page is not left spinning");
        assert!(page.items.error.is_none());
        // When TIDAL confirms, the next page is asked for at once.
        app.handle_api(stale_header("1970-01-01T00:00:02.000+0000", 120));
        assert_eq!(
            app.backend.take_playlist_item_requests(),
            [("edited".into(), 50, 7)]
        );
        // A disagreement that lasts past the limit no longer holds rows back.
        let mut page = stale_test_page(50, 120, true);
        page.snapshot_since = Instant::now().checked_sub(Duration::from_secs(61));
        assert!(!page.rows_gated());
    }

