    /// A play-search that finishes late never replaces a newer search or
    /// something the user started after it, and a play asked for before it
    /// never supersedes it, even within one batch of commands.
    #[test]
    fn a_late_play_search_never_overrides_a_newer_choice() {
        // #given
        let ctx = egui::Context::default();
        let mut app = headless_app();
        let queue: std::sync::Arc<std::sync::Mutex<Vec<ControlCommand>>> = Default::default();
        app.control_commands = Some(std::sync::Arc::clone(&queue));
        let search = |query: &str| ControlCommand::PlaySearch {
            kind: "track".to_owned(),
            query: query.to_owned(),
        };
        let found = |serial: u64, uri: &str| ApiResponse::PlaySearch {
            query: "words".to_owned(),
            serial,
            result: Ok(Some(uri.to_owned())),
        };
        let send = |app: &mut App, commands: Vec<ControlCommand>| {
            queue.lock().expect("the queue").extend(commands);
            app.handle_control_commands();
            app.apply_actions(&ctx);
            app.play_search_serial
        };
        let answer = |app: &mut App, serial: u64, uri: &str| {
            app.handle_api(found(serial, uri));
            app.apply_actions(&ctx);
        };
        // The context the app last started, shown at once.
        let playing = |app: &App| {
            app.assumed_context
                .as_ref()
                .map(|context| context.uri.clone())
        };

        // #when two searches are sent and the older answers last
        let first = send(&mut app, vec![search("first")]);
        let second = send(&mut app, vec![search("second")]);
        answer(&mut app, second, "tidal:track:second");
        answer(&mut app, first, "tidal:track:first");

        // #then only the newer search plays
        assert_eq!(playing(&app).as_deref(), Some("tidal:track:second"));

        // #when the user plays something before a search answers
        let third = send(&mut app, vec![search("third")]);
        send(
            &mut app,
            vec![ControlCommand::PlayUri("tidal:album:chosen".to_owned())],
        );
        answer(&mut app, third, "tidal:track:third");

        // #then the user's choice stands
        assert_eq!(playing(&app).as_deref(), Some("tidal:album:chosen"));

        // #when one batch asks for a URI and then a search
        queue.lock().expect("the queue").extend([
            ControlCommand::PlayUri("tidal:album:older".to_owned()),
            search("fourth"),
        ]);
        app.handle_control_commands();

        // #then the search takes precedence after the URI, in command order
        assert!(
            matches!(
                app.actions.as_slice(),
                [Action::PlayContext { .. }, Action::PlaySearch { query, .. }] if query == "fourth"
            ),
            "{:?}",
            app.actions
        );
        app.apply_actions(&ctx);
        let fourth = app.play_search_serial;
        answer(&mut app, fourth, "tidal:track:fourth");

        // #then the search, asked for last, still plays
        assert_eq!(playing(&app).as_deref(), Some("tidal:track:fourth"));

        // #when a search arrives in the same frame as an older search's answer
        let fifth = send(&mut app, vec![search("fifth")]);
        queue.lock().expect("the queue").push(search("sixth"));
        app.handle_control_commands();
        app.handle_api(found(fifth, "tidal:track:fifth"));
        app.apply_actions(&ctx);
        // The serial the newer search was sent with; a stray play of the
        // older match would have moved the current one past it.
        let sixth = fifth.wrapping_add(1);
        answer(&mut app, sixth, "tidal:track:sixth");

        // #then the older answer, though current when it arrived, never plays
        assert_eq!(playing(&app).as_deref(), Some("tidal:track:sixth"));

        // #when a play waits for the engine and a search is sent meanwhile
        send(
            &mut app,
            vec![ControlCommand::PlayUri("tidal:album:waiting".to_owned())],
        );
        assert!(app.queued_play.is_some(), "the engine is not connected");
        let seventh = send(&mut app, vec![search("seventh")]);
        app.handle_playback(LocalPlayback::Ready {
            device_id: "local".to_owned(),
        });
        answer(&mut app, seventh, "tidal:track:seventh");

        // #then replaying the waiting play does not cancel the newer search
        assert_eq!(playing(&app).as_deref(), Some("tidal:track:seventh"));

        // #when the listener pauses, skips or steps back before a search answers
        for transport in [Action::TogglePlay, Action::Next, Action::Previous] {
            let pending = send(&mut app, vec![search("pending")]);
            app.actions.push(transport.clone());
            app.apply_actions(&ctx);
            answer(&mut app, pending, "tidal:track:pending");

            // #then that choice stands
            assert_eq!(
                playing(&app).as_deref(),
                Some("tidal:track:seventh"),
                "{transport:?}"
            );
        }

        // #when the listener only changes the volume
        let louder = send(&mut app, vec![search("louder")]);
        app.actions.push(Action::SetVolume(80));
        app.apply_actions(&ctx);
        answer(&mut app, louder, "tidal:track:louder");

        // #then the search still plays its match
        assert_eq!(playing(&app).as_deref(), Some("tidal:track:louder"));
    }

    #[test]
    fn restricted_remote_controls_require_a_ready_playback_session() {
        let mut app = headless_app();
        app.remote = Some(RemoteSnapshot {
            state: PlaybackState {
                item: Some(queued_song("tidal:track:song")),
                device: Some(Device {
                    id: Some("office".into()),
                    is_restricted: true,
                    supports_volume: Some(true),
                    ..Default::default()
                }),
                ..Default::default()
            },
            received_at: Instant::now(),
        });
        for ready in [false, true] {
            app.local_ready = ready;
            let now = app.now_playing_live().unwrap();
            assert_eq!(now.can_control, ready);
            assert_eq!(now.can_set_volume, ready);
        }
        app.remote
            .as_mut()
            .unwrap()
            .state
            .device
            .as_mut()
            .unwrap()
            .supports_volume = Some(false);
        assert!(!app.now_playing_live().unwrap().can_set_volume);
        app.backend.shutdown();
    }

    /// `play` and `pause` say what state to end in, so the one that would
    /// undo the current state does nothing.
    #[test]
    fn play_and_pause_do_not_toggle_the_wrong_way() {
        let mut app = headless_app();
        let queue: std::sync::Arc<std::sync::Mutex<Vec<ControlCommand>>> = Default::default();
        app.control_commands = Some(std::sync::Arc::clone(&queue));

        // Nothing is playing in a headless app, so `pause` has nothing to do
        // and `play` asks for the toggle.
        queue
            .lock()
            .expect("the queue")
            .extend([ControlCommand::Pause, ControlCommand::Play]);
        app.handle_control_commands();

        assert!(
            matches!(app.actions.as_slice(), [Action::TogglePlay]),
            "{:?}",
            app.actions
        );
    }

    /// A song still loading on the first play reads as playing, as the
    /// engine will play it: a media key's Play does not toggle it to a
    /// pause, and Pause does. A song loading paused (a restored session)
    /// is the other way round.
    #[test]
    fn play_and_pause_during_the_first_load_act_on_what_will_play() {
        use crate::tidal_engine::LocalTrack;
        let mut app = headless_app();
        let queue: std::sync::Arc<std::sync::Mutex<Vec<ControlCommand>>> = Default::default();
        app.control_commands = Some(std::sync::Arc::clone(&queue));
        app.local.track = Some(LocalTrack {
            uri: "tidal:track:1".into(),
            title: "Song".into(),
            duration_ms: 1_000,
            ..LocalTrack::default()
        });
        app.local.track_sequence = 1;
        app.local.playback = Playback::Loading;
        app.local.loading = true;
        let press = |app: &mut App, command: ControlCommand| {
            app.actions.clear();
            queue.lock().expect("the queue").push(command);
            app.handle_control_commands();
            app.actions.clone()
        };
        assert!(app.now_playing().is_some_and(|now| now.playing));
        assert!(
            press(&mut app, ControlCommand::Play).is_empty(),
            "already playing"
        );
        assert!(matches!(
            press(&mut app, ControlCommand::Pause).as_slice(),
            [Action::TogglePlay]
        ));

        app.local.held_paused = true;
        assert!(app.now_playing().is_some_and(|now| !now.playing));
        assert!(
            press(&mut app, ControlCommand::Pause).is_empty(),
            "already paused"
        );
        assert!(matches!(
            press(&mut app, ControlCommand::Play).as_slice(),
            [Action::TogglePlay]
        ));
        app.backend.shutdown();
    }

    /// A link from outside waits for the account and then opens its page;
    /// a song's link opens the album the song is on.
    #[test]
    fn a_link_waits_for_the_account_and_then_opens_its_page() {
        use crate::api::models::{Album, Track};

        // #given a signed-out app handed a playlist link
        let mut app = headless_app();
        let ctx = egui::Context::default();
        app.actions
            .push(Action::OpenLink("tidal:playlist:pl1".into()));
        app.apply_actions(&ctx);

        // #then the window is asked for but the page waits
        assert_eq!(*app.page(), Page::Home);
        assert_eq!(app.pending_link.as_deref(), Some("tidal:playlist:pl1"));

        // #when the account arrives
        app.user = Some(User {
            id: "me".into(),
            ..User::default()
        });
        app.open_pending_link();

        // #then the playlist opens, once
        assert_eq!(*app.page(), Page::Playlist("pl1".into()));
        assert_eq!(app.pending_link, None);

        // #when a song whose album is known is linked
        app.track_cache.insert(
            "t1".into(),
            Track {
                id: Some("t1".into()),
                uri: "tidal:track:t1".into(),
                album: Some(Album {
                    id: "al1".into(),
                    ..Album::default()
                }),
                ..Track::default()
            },
        );
        app.actions.push(Action::OpenLink("tidal:track:t1".into()));
        app.apply_actions(&ctx);

        // #then its album's page opens
        assert_eq!(*app.page(), Page::Album("al1".into()));
        assert_eq!(app.pending_link, None);

        // #when a song still unknown is linked
        app.actions.push(Action::OpenLink("tidal:track:t2".into()));
        app.apply_actions(&ctx);

        // #then the link waits for TIDAL's answer rather than guessing
        assert_eq!(*app.page(), Page::Album("al1".into()));
        assert_eq!(app.pending_link.as_deref(), Some("tidal:track:t2"));
        assert!(app.track_requests.contains("t2"));

        // #when TIDAL has no such song
        app.handle_api(ApiResponse::Track {
            id: "t2".into(),
            result: Err(crate::api::client::ApiError::Status {
                status: 404,
                message: "not found".into(),
            }),
        });

        // #then the link is given up on and the user told
        assert_eq!(app.pending_link, None);
        assert!(
            app.toasts
                .iter()
                .any(|toast| toast.message.contains("Cannot open"))
        );
    }

    /// A link to something the app has no page for is refused with a word,
